/* Week 3 Session 13 | HackerRank: Java Priority Queue */
import java.util.*;public class JavaPriorityQueue{static class Student{String n;double cg;int id;Student(String n,double c,int i){this.n=n;cg=c;id=i;}}public static void main(String[]x){Scanner s=new Scanner(System.in);int q=s.nextInt();PriorityQueue<Student>pq=new PriorityQueue<>((a,b)->a.cg!=b.cg?Double.compare(b.cg,a.cg):a.n.equals(b.n)?Integer.compare(a.id,b.id):a.n.compareTo(b.n));while(q-->0){String op=s.next();if(op.equals("ENTER"))pq.add(new Student(s.next(),s.nextDouble(),s.nextInt()));else if(op.equals("SERVED")&&!pq.isEmpty())pq.poll();}if(pq.isEmpty())System.out.println("EMPTY");else{List<Student>l=new ArrayList<>(pq);l.sort(pq.comparator());for(Student z:l)System.out.println(z.n);}}}
